// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; brifing hazırlanamadı → ' + m);
  }
};
_dosyaKontrol('Görevleri Oku (Brifing)', 'Görevleri Çıkar (Brifing)', 'gorevler.json');
_dosyaKontrol('Notları Oku (Brifing)', 'Notları Çıkar (Brifing)', 'notlar.json');
_dosyaKontrol('Harcamaları Oku (Brifing)', 'Harcamaları Çıkar (Brifing)', 'harcamalar.json');

const _liste = (dugum, alan) => {
  const j = $(dugum).first().json || {};
  const d = (j.data && j.data[alan]) || [];
  return Array.isArray(d) ? d.map((x) => ({ ...x })) : [];
};
const HAVA = {
  0: ['Açık', '☀️'], 1: ['Az bulutlu', '🌤'], 2: ['Parçalı bulutlu', '⛅'], 3: ['Çok bulutlu', '☁️'],
  45: ['Sisli', '🌫'], 48: ['Kırağılı sis', '🌫'],
  51: ['Hafif çisenti', '🌦'], 53: ['Çisenti', '🌦'], 55: ['Yoğun çisenti', '🌦'],
  61: ['Hafif yağmur', '🌧'], 63: ['Yağmurlu', '🌧'], 65: ['Kuvvetli yağmur', '🌧'],
  66: ['Dondurucu yağmur', '🌧'], 67: ['Dondurucu yağmur', '🌧'],
  71: ['Hafif kar', '🌨'], 73: ['Kar yağışlı', '🌨'], 75: ['Yoğun kar', '❄️'], 77: ['Kar taneli', '🌨'],
  80: ['Sağanak', '🌦'], 81: ['Sağanak', '🌦'], 82: ['Kuvvetli sağanak', '⛈'],
  85: ['Kar sağanağı', '🌨'], 86: ['Kar sağanağı', '🌨'],
  95: ['Gök gürültülü', '⛈'], 96: ['Dolulu fırtına', '⛈'], 99: ['Dolulu fırtına', '⛈'],
};

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' TL';

const gorevler = _liste('Görevleri Çıkar (Brifing)', 'gorevler');
const notlar = _liste('Notları Çıkar (Brifing)', 'notlar');
const harcamalar = _liste('Harcamaları Çıkar (Brifing)', 'harcamalar');

const simdi = new Date();
const bas = new Date(simdi); bas.setHours(0, 0, 0, 0);
const bit = new Date(bas); bit.setDate(bit.getDate() + 1);
const zaman = (s) => new Date(s).getTime();
const gunAdi = simdi.toLocaleDateString('tr-TR', { weekday: 'long', day: 'numeric', month: 'long' });

const satirlar = ['☀️ Günaydın! ' + gunAdi];
const htmlBolum = [];

// ── Hava durumu (Open-Meteo, anahtar gerektirmez) ────────────────────────────
const havaJson = $('Hava Durumunu Al').first().json || {};
const g = havaJson.daily;
if (g && Array.isArray(g.temperature_2m_max) && g.temperature_2m_max.length) {
  const kod = Number((g.weather_code || [])[0]);
  const [ad, ikon] = HAVA[kod] || ['', '🌡'];
  const enYuksek = Math.round(g.temperature_2m_max[0]);
  const enDusuk = Math.round((g.temperature_2m_min || [])[0]);
  const yagis = Number((g.precipitation_probability_max || [])[0]);
  const sehir = String($env.HAVA_SEHIR || '').trim();
  let h = ikon + ' ' + (sehir ? sehir + ': ' : '') + (ad ? ad + ', ' : '') + enDusuk + '° / ' + enYuksek + '°';
  if (Number.isFinite(yagis) && yagis >= 30) h += ' · ☔ yağış %' + yagis;
  satirlar.push('', h);
  htmlBolum.push('<p>' + esc(h) + '</p>');
} else if (havaJson.error) {
  satirlar.push('', '🌡 Hava durumu alınamadı.');
}

// ── Döviz kuru (TCMB günlük XML — hafta sonu son iş gününü verir) ────────────
const kurMetin = String(($('Kurları Al (TCMB)').first().json || {}).data || '');
const kurOku = (kod) => {
  const blok = kurMetin.match(new RegExp('<Currency[^>]*CurrencyCode="' + kod + '"[\\s\\S]*?</Currency>'));
  if (!blok) return null;
  const s = blok[0].match(/<ForexSelling>([\d.]+)<\/ForexSelling>/);
  const n = s ? Number(s[1]) : NaN;
  return Number.isFinite(n) && n > 0 ? n : null;
};
const usd = kurOku('USD');
const eur = kurOku('EUR');
if (usd || eur) {
  const parcalar = [];
  if (usd) parcalar.push('$ ' + usd.toFixed(2));
  if (eur) parcalar.push('€ ' + eur.toFixed(2));
  const k = '💱 ' + parcalar.join('  ·  ');
  satirlar.push(k);
  htmlBolum.push('<p>' + esc(k) + '</p>');
}

// ── Bugünün takvim etkinlikleri (workflow 08 aktifse dosyadan gelir) ─────────
// Takvim bu workflow'a bağlı değil: 08 zaten ayrı mesaj gönderiyor.

// ── Açık görevler ────────────────────────────────────────────────────────────
const acik = gorevler.filter((x) => x && x.durum !== 'tamam');
if (acik.length) {
  const ilk = acik.slice(0, 8);
  satirlar.push('', '📋 Açık görev (' + acik.length + '):');
  ilk.forEach((x) => satirlar.push('#' + x.id + ' ' + x.baslik));
  if (acik.length > ilk.length) satirlar.push('… ve ' + (acik.length - ilk.length) + ' tane daha');
  htmlBolum.push('<h3>📋 Açık görev (' + acik.length + ')</h3><ul>' +
    ilk.map((x) => '<li>#' + esc(x.id) + ' ' + esc(x.baslik) + '</li>').join('') + '</ul>');
} else {
  satirlar.push('', '📋 Açık görev yok. 🎉');
  htmlBolum.push('<p>📋 Açık görev yok. 🎉</p>');
}

// ── Bugünün hatırlatmaları ───────────────────────────────────────────────────
const bugunkuNotlar = notlar
  .filter((n) => n && n.hatirlat && n.durum !== 'gonderildi' &&
                 zaman(n.hatirlat) >= bas.getTime() && zaman(n.hatirlat) < bit.getTime())
  .sort((a, b) => zaman(a.hatirlat) - zaman(b.hatirlat));
if (bugunkuNotlar.length) {
  const ss = (s) => new Date(s).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });
  satirlar.push('', '⏰ Bugünün hatırlatmaları:');
  bugunkuNotlar.forEach((n) => satirlar.push(ss(n.hatirlat) + ' ' + n.metin));
  htmlBolum.push('<h3>⏰ Bugünün hatırlatmaları</h3><ul>' +
    bugunkuNotlar.map((n) => '<li>' + esc(ss(n.hatirlat)) + ' ' + esc(n.metin) + '</li>').join('') + '</ul>');
}

// ── Dün ne harcandı ──────────────────────────────────────────────────────────
const dunBas = new Date(bas); dunBas.setDate(dunBas.getDate() - 1);
const dunkuler = harcamalar.filter((x) => x && typeof x.tutar === 'number' &&
  zaman(x.tarih) >= dunBas.getTime() && zaman(x.tarih) < bas.getTime());
if (dunkuler.length) {
  const toplam = dunkuler.reduce((t, x) => t + x.tutar, 0);
  const h = '💸 Dün: ' + tl(toplam) + ' (' + dunkuler.length + ' kayıt)';
  satirlar.push('', h);
  htmlBolum.push('<p>' + esc(h) + '</p>');
}

const text = satirlar.join('\n');
const html = '<div style="font-family:system-ui,sans-serif;line-height:1.5">' +
  '<h2>☀️ Günaydın! ' + esc(gunAdi) + '</h2>' + htmlBolum.join('') + '</div>';

return [{ json: { text, html, konu: '☀️ Günaydın — ' + gunAdi, gonderilecek: true } }];

// Telegram kuruluysa brifing oraya gider.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE brifing mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];
